begin;
do $$ declare v_organization_id uuid; begin select id into strict v_organization_id from public.organizations limit 1;insert into public.dtg_order_history_summaries(organization_id,order_no,printed_garments,printed_prints,source_max_audit_id)values(v_organization_id,'TEST-DTG-HISTORY',1,2,'10')on conflict(organization_id,order_no)do update set printed_garments=excluded.printed_garments,printed_prints=excluded.printed_prints,source_max_audit_id=excluded.source_max_audit_id,refreshed_at=statement_timestamp();insert into public.dtg_order_history_summaries(organization_id,order_no,printed_garments,printed_prints,source_max_audit_id)values(v_organization_id,'TEST-DTG-HISTORY',2,4,'11')on conflict(organization_id,order_no)do update set printed_garments=excluded.printed_garments,printed_prints=excluded.printed_prints,source_max_audit_id=excluded.source_max_audit_id,refreshed_at=statement_timestamp();if(select count(*) from public.dtg_order_history_summaries where organization_id=v_organization_id and order_no='TEST-DTG-HISTORY')<>1 then raise exception'DTG_HISTORY_NOT_IDEMPOTENT';end if;if(select printed_garments from public.dtg_order_history_summaries where organization_id=v_organization_id and order_no='TEST-DTG-HISTORY')<>2 then raise exception'DTG_HISTORY_NOT_REPLACED';end if;end $$;
rollback;
